<?php
namespace Tests\Feature;
use App\Models\{BookingServis,JenisServis,KendaraanPelanggan,User};
use App\Services\BookingServisService;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
class BookingServisStage4CTest extends TestCase
{
 use DatabaseTransactions;
 private function user(string $role):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$role))->firstOrFail();}
 private function otherCustomer(User $user):User{return User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->where('id_user','<>',$user->id_user)->firstOrFail();}
 private function vehicle(User $u,string $status='aktif'):KendaraanPelanggan{return $u->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Test Vehicle','nomor_polisi'=>'QA-'.random_int(1000,9999),'status'=>$status]);}
 private function validData(User $u):array{$v=$this->vehicle($u);$t=JenisServis::where('status','aktif')->firstOrFail();return [$u,$v,$t];}
 public function test_baseline_import_is_present():void{$this->assertSame(1,BookingServis::count());$this->assertDatabaseHas('booking_servis',['id_booking_servis'=>1,'kode_booking'=>'BSV-202609-52D02542']);}
 public function test_customer_can_create_booking_for_own_active_vehicle():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$b=app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00','Keluhan','Catatan');$this->assertSame('menunggu',$b->status);$this->assertStringStartsWith('BSV-', $b->kode_booking);}
 public function test_vehicle_ownership_is_enforced():void{$a=$this->user('pelanggan');$b=$this->otherCustomer($a);$other=$this->vehicle($b);$type=JenisServis::where('status','aktif')->firstOrFail();$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(BookingServisService::class)->create($a->pelanggan->id_pelanggan,$other->id_kendaraan_pelanggan,$type->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);}
 public function test_id_pelanggan_spoof_is_ignored_by_http_flow():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$this->withoutMiddleware()->actingAs($u)->post('/pelanggan/booking-servis',['id_kendaraan_pelanggan'=>$v->id_kendaraan_pelanggan,'id_jenis_servis'=>$t->id_jenis_servis,'tanggal'=>now()->addDay()->toDateString(),'jam'=>'10:00','id_pelanggan'=>999,'status'=>'selesai'])->assertRedirect();$this->assertSame($u->pelanggan->id_pelanggan,BookingServis::latest('id_booking_servis')->value('id_pelanggan'));}
 public function test_nonaktif_vehicle_is_blocked():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$v->update(['status'=>'nonaktif']);$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);}
 public function test_nonaktif_service_type_is_blocked():void{$u=$this->user('pelanggan');$v=$this->vehicle($u);$t=JenisServis::where('status','aktif')->firstOrFail();$t->update(['status'=>'nonaktif']);$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);}
 public function test_past_date_and_invalid_time_are_blocked():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$svc=app(BookingServisService::class);$this->expectException(\RuntimeException::class);$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->subDay()->toDateString(),'10:00',null,null);}
 public function test_native_has_no_schedule_conflict_rule():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$svc=app(BookingServisService::class);$a=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$this->assertNotSame($a->id_booking_servis,$b->id_booking_servis);}
 public function test_admin_and_petugas_can_confirm():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$svc=app(BookingServisService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$this->actingAs($this->user('petugas'))->post('/petugas/booking-servis/'.$b->id_booking_servis.'/confirm')->assertRedirect();$this->assertSame('diterima',$b->fresh()->status);}
 public function test_reject_transition_is_recorded():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$b=app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);app(BookingServisService::class)->reject($b->id_booking_servis);$this->assertSame('ditolak',$b->fresh()->status);}
 public function test_customer_can_cancel_waiting_or_accepted():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$svc=app(BookingServisService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$svc->cancel($b->id_booking_servis,$u->pelanggan->id_pelanggan);$this->assertSame('dibatalkan',$b->fresh()->status);}
 public function test_customer_cannot_cancel_other_booking():void{$a=$this->user('pelanggan');$b=$this->otherCustomer($a);$v=$this->vehicle($b);$t=JenisServis::where('status','aktif')->firstOrFail();$booking=app(BookingServisService::class)->create($b->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$this->expectException(\RuntimeException::class);app(BookingServisService::class)->cancel($booking->id_booking_servis,$a->pelanggan->id_pelanggan);}
 public function test_invalid_transition_is_blocked():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$svc=app(BookingServisService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$svc->reject($b->id_booking_servis);$this->expectException(\RuntimeException::class);$svc->confirm($b->id_booking_servis);}
 public function test_customer_cannot_view_other_booking():void{$a=$this->user('pelanggan');$b=$this->otherCustomer($a);$v=$this->vehicle($b);$t=JenisServis::where('status','aktif')->firstOrFail();$booking=app(BookingServisService::class)->create($b->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$this->actingAs($a)->get('/pelanggan/booking-servis/'.$booking->id_booking_servis)->assertForbidden();}
 public function test_role_and_guest_authorization():void{$this->get('/pelanggan/booking-servis')->assertRedirect('/login');$this->actingAs($this->user('pelanggan'))->get('/admin/booking-servis')->assertForbidden();$this->actingAs($this->user('admin'))->get('/admin/booking-servis')->assertOk();}
 public function test_status_field_cannot_be_set_by_request():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$this->withoutMiddleware()->actingAs($u)->post('/pelanggan/booking-servis',['id_kendaraan_pelanggan'=>$v->id_kendaraan_pelanggan,'id_jenis_servis'=>$t->id_jenis_servis,'tanggal'=>now()->addDay()->toDateString(),'jam'=>'10:00','status'=>'selesai'])->assertRedirect();$this->assertSame('menunggu',BookingServis::latest('id_booking_servis')->value('status'));}
 public function test_no_notification_is_created_when_native_has_none():void{$before=\App\Models\Notifikasi::count();[$u,$v,$t]=$this->validData($this->user('pelanggan'));app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$this->assertSame($before,\App\Models\Notifikasi::count());}
 public function test_rejected_booking_cannot_be_reactivated():void{[$u,$v,$t]=$this->validData($this->user('pelanggan'));$svc=app(BookingServisService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$svc->reject($b->id_booking_servis);$this->expectException(\RuntimeException::class);$svc->cancel($b->id_booking_servis,$u->pelanggan->id_pelanggan);}
 public function test_list_eager_loads_booking_relations_and_regression_modules():void{$this->actingAs($this->user('petugas'))->get('/petugas/booking-servis')->assertOk();$this->actingAs($this->user('admin'))->get('/admin/jenis-servis')->assertOk();$this->get('/mobil')->assertOk();}
}
